CREATE DATABASE IF NOT EXISTS compara_tech_gt CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE compara_tech_gt;
CREATE TABLE categoria (idcategoria INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(100) NOT NULL UNIQUE, estado TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE marca (idmarca INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(100) NOT NULL UNIQUE, estado TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE tienda (idtienda INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(120) NOT NULL UNIQUE, url VARCHAR(255) NOT NULL, logo VARCHAR(255) NULL, estado TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE producto (idproducto INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, idcategoria INT UNSIGNED NOT NULL, idmarca INT UNSIGNED NULL, nombre VARCHAR(255) NOT NULL, modelo VARCHAR(150) NULL, sku_global VARCHAR(150) NULL UNIQUE, imagen VARCHAR(500) NULL, descripcion TEXT NULL, estado TINYINT(1) NOT NULL DEFAULT 1, creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (idcategoria) REFERENCES categoria(idcategoria), FOREIGN KEY (idmarca) REFERENCES marca(idmarca), INDEX idx_producto_busqueda (nombre, modelo)) ENGINE=InnoDB;
CREATE TABLE producto_tienda (idproducto_tienda INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, idproducto INT UNSIGNED NOT NULL, idtienda INT UNSIGNED NOT NULL, nombre_tienda VARCHAR(255) NOT NULL, sku_tienda VARCHAR(150) NULL, url VARCHAR(500) NOT NULL, imagen VARCHAR(500) NULL, disponibilidad TINYINT(1) NOT NULL DEFAULT 0, estado TINYINT(1) NOT NULL DEFAULT 1, creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_producto_tienda (idproducto, idtienda), UNIQUE KEY uk_sku_tienda (idtienda, sku_tienda), FOREIGN KEY (idproducto) REFERENCES producto(idproducto) ON DELETE CASCADE, FOREIGN KEY (idtienda) REFERENCES tienda(idtienda), INDEX idx_pt_disponibilidad (disponibilidad, estado)) ENGINE=InnoDB;
CREATE TABLE precio (idprecio BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, idproducto_tienda INT UNSIGNED NOT NULL, precio DECIMAL(12,2) NOT NULL, precio_anterior DECIMAL(12,2) NULL, moneda CHAR(3) NOT NULL DEFAULT 'GTQ', disponible TINYINT(1) NOT NULL DEFAULT 0, fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (idproducto_tienda) REFERENCES producto_tienda(idproducto_tienda) ON DELETE CASCADE, INDEX idx_precio_historial (idproducto_tienda, fecha), INDEX idx_precio_actual (idproducto_tienda, fecha DESC)) ENGINE=InnoDB;
CREATE TABLE producto_especificacion (idproducto_especificacion INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, idproducto INT UNSIGNED NOT NULL, atributo VARCHAR(100) NOT NULL, valor VARCHAR(255) NOT NULL, UNIQUE KEY uk_especificacion (idproducto, atributo), FOREIGN KEY (idproducto) REFERENCES producto(idproducto) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE scraper_log (idscraper_log BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, idtienda INT UNSIGNED NULL, fecha_inicio DATETIME NOT NULL, fecha_fin DATETIME NULL, productos_encontrados INT UNSIGNED NOT NULL DEFAULT 0, productos_actualizados INT UNSIGNED NOT NULL DEFAULT 0, errores INT UNSIGNED NOT NULL DEFAULT 0, estado ENUM('ejecutando','completado','error') NOT NULL DEFAULT 'ejecutando', mensaje TEXT NULL, FOREIGN KEY (idtienda) REFERENCES tienda(idtienda) ON DELETE SET NULL, INDEX idx_scraper_log_fecha (fecha_inicio DESC)) ENGINE=InnoDB;
CREATE TABLE producto_match_pendiente (idmatch BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, idproducto_tienda INT UNSIGNED NULL, idtienda INT UNSIGNED NULL, nombre_detectado VARCHAR(255) NOT NULL, nombre_tienda VARCHAR(255) NULL, sku_tienda VARCHAR(150) NULL, url VARCHAR(500) NULL, imagen VARCHAR(500) NULL, precio DECIMAL(12,2) NULL, moneda CHAR(3) NULL DEFAULT 'GTQ', disponible TINYINT(1) NULL DEFAULT 0, puntuacion DECIMAL(5,2) NOT NULL, estado ENUM('pendiente','aprobado','rechazado') NOT NULL DEFAULT 'pendiente', creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (idproducto_tienda) REFERENCES producto_tienda(idproducto_tienda) ON DELETE SET NULL, FOREIGN KEY (idtienda) REFERENCES tienda(idtienda) ON DELETE SET NULL) ENGINE=InnoDB;
